     send(sock,':%s!%s@host JOIN %s'%(st['nick'],st['nick'],name));send(sock,':irc 353 %s = %s :%s'%(st['nick'],name,st['nick']));send(sock,':irc 366 %s %s :End of NAMES list'%(st['nick'],name))
    elif cmd=='PRIVMSG':
     name=arg; body=rest[1:] if rest.startswith(':') else rest; ch=lookup(name)
